// Convert input points to CGAL points
CGALPoint cgalP1(p1.x(), p1.y(), p1.z());
CGALPoint cgalP2(p2.x(), p2.y(), p2.z());

// Create a CGAL segment from the two points
CGAL::Segment_3<K> segment(cgalP1, cgalP2);

// Query the AABB tree for intersections with the segment
std::list<Tree::Object_and_primitive_id> intersections;
tree.all_intersections(segment, std::back_inserter(intersections));

// Count the number of unique primitives intersected
std::set<typename std::list<CGALTriangle>::iterator> uniquePrimitives;
for (const auto& intersection : intersections) {
    const CGALTriangle* triangle = std::get<CGALTriangle>(&(intersection->first));
    if (triangle) {
        uniquePrimitives.insert(intersection->second);
    }
}

return static_cast<int>(uniquePrimitives.size());

